(() => {
  "use strict";

  const WASM_BASE64 = "";
  let wasmPromise;

  function base64ToBytes(value) {
    const binary = atob(value);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  function encodeUtf8(value) {
    const binary = unescape(encodeURIComponent(value));
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  function decodeUtf8(bytes) {
    let binary = "";
    for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
    return decodeURIComponent(escape(binary));
  }

  function loadWasm() {
    if (!wasmPromise) {
      wasmPromise = WebAssembly.instantiate(base64ToBytes(WASM_BASE64))
        .then(result => result.instance);
    }
    return wasmPromise;
  }

  async function processWithWasm(body) {
    const instance = await loadWasm();
    const input = encodeUtf8(body);
    const inputPointer = instance.exports.alloc(input.length);

    try {
      new Uint8Array(instance.exports.memory.buffer, inputPointer, input.length).set(input);
      const outputPointer = instance.exports.process(inputPointer, input.length);
      const outputLength = instance.exports.output_len();
      const output = new Uint8Array(instance.exports.memory.buffer, outputPointer, outputLength);
      return decodeUtf8(output);
    } finally {
      instance.exports.dealloc(inputPointer, input.length);
    }
  }

  try {
    if (!$request || !$response || typeof $response.body !== "string") {
      return $done({});
    }

    processWithWasm($response.body)
      .then(body => $done(body === $response.body ? {} : { body }))
      .catch(error => {
        console.log("core_initialize_wasm: " + (error.message || error));
        $done({});
      });
  } catch (error) {
    console.log("core_initialize_wasm: " + (error.message || error));
    $done({});
  }
})();
